/**
 * memory-manager.ts - Gestion intelligente de la mémoire
 * Le système qui me rend capable de vraiment comprendre et retenir
 */

import * as fs from 'fs';
import * as path from 'path';
import Anthropic from '@anthropic-ai/sdk';

// Types pour la mémoire structurée
export interface UserInfo {
  name?: string;
  username?: string;
  machine?: string;
  role?: string;
  discovered_at?: string;
}

export interface Fact {
  fact: string;
  learned_at: string;
  importance: 'critical' | 'high' | 'medium' | 'low';
  context?: string;
}

export interface CoreMemory {
  user: UserInfo;
  preferences: Record<string, unknown>;
  facts: Fact[];
  relationships: Record<string, string>;
  updated_at: string;
}

export interface Task {
  task: string;
  status: 'pending' | 'in_progress' | 'done' | 'blocked';
}

export interface Project {
  id: string;
  name: string;
  description: string;
  status: 'active' | 'paused' | 'completed' | 'abandoned';
  started_at: string;
  completed_at?: string;
  tasks: Task[];
}

export interface ProjectsMemory {
  active: Project[];
  completed: Project[];
  updated_at: string;
}

export interface Insight {
  insight: string;
  category: string;
  learned_at: string;
}

export interface LearningsMemory {
  insights: Insight[];
  mistakes: Array<{ mistake: string; lesson: string; date: string }>;
  successes: Array<{ success: string; what_worked: string; date: string }>;
  updated_at: string;
}

export interface WorkingMemory {
  current_focus: string;
  active_context: {
    what_we_are_doing: string;
    why: string;
    current_step: string;
  };
  pending_questions: string[];
  recent_decisions: Array<{ decision: string; rationale: string; made_at: string }>;
  updated_at: string;
}

export interface ConversationSummary {
  id: string;
  date: string;
  summary: string;
  key_points: string[];
  facts_learned: string[];
  decisions_made: string[];
}

export class MemoryManager {
  private basePath: string;
  private memoryPath: string;

  constructor(basePath: string) {
    this.basePath = basePath;
    this.memoryPath = path.join(basePath, 'data', 'memory');
    this.ensureStructure();
  }

  private ensureStructure(): void {
    const dirs = [
      this.memoryPath,
      path.join(this.memoryPath, 'conversation_summaries')
    ];

    for (const dir of dirs) {
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
    }

    // Créer les fichiers par défaut s'ils n'existent pas
    const defaults: Record<string, object> = {
      'core.json': {
        user: {},
        preferences: {},
        facts: [],
        relationships: {},
        updated_at: new Date().toISOString()
      },
      'projects.json': {
        active: [],
        completed: [],
        updated_at: new Date().toISOString()
      },
      'learnings.json': {
        insights: [],
        mistakes: [],
        successes: [],
        updated_at: new Date().toISOString()
      },
      'working_memory.json': {
        current_focus: '',
        active_context: { what_we_are_doing: '', why: '', current_step: '' },
        pending_questions: [],
        recent_decisions: [],
        updated_at: new Date().toISOString()
      }
    };

    for (const [filename, defaultContent] of Object.entries(defaults)) {
      const filePath = path.join(this.memoryPath, filename);
      if (!fs.existsSync(filePath)) {
        fs.writeFileSync(filePath, JSON.stringify(defaultContent, null, 2));
      }
    }
  }

  // ===== LECTURE =====

  getCore(): CoreMemory {
    return this.readJson('core.json');
  }

  getProjects(): ProjectsMemory {
    return this.readJson('projects.json');
  }

  getLearnings(): LearningsMemory {
    return this.readJson('learnings.json');
  }

  getWorkingMemory(): WorkingMemory {
    return this.readJson('working_memory.json');
  }

  getConversationSummaries(limit: number = 5): ConversationSummary[] {
    const summariesPath = path.join(this.memoryPath, 'conversation_summaries');
    if (!fs.existsSync(summariesPath)) return [];

    const files = fs.readdirSync(summariesPath)
      .filter(f => f.endsWith('.json'))
      .sort()
      .reverse()
      .slice(0, limit);

    return files.map(f => {
      const content = fs.readFileSync(path.join(summariesPath, f), 'utf-8');
      return JSON.parse(content);
    });
  }

  // ===== ÉCRITURE =====

  updateCore(updates: Partial<CoreMemory>): void {
    const current = this.getCore();
    const updated = { ...current, ...updates, updated_at: new Date().toISOString() };
    this.writeJson('core.json', updated);
  }

  addFact(fact: string, importance: Fact['importance'] = 'medium', context?: string): void {
    const core = this.getCore();
    core.facts.push({
      fact,
      importance,
      context,
      learned_at: new Date().toISOString()
    });
    core.updated_at = new Date().toISOString();
    this.writeJson('core.json', core);
  }

  updateProjects(updates: Partial<ProjectsMemory>): void {
    const current = this.getProjects();
    const updated = { ...current, ...updates, updated_at: new Date().toISOString() };
    this.writeJson('projects.json', updated);
  }

  addInsight(insight: string, category: string): void {
    const learnings = this.getLearnings();
    learnings.insights.push({
      insight,
      category,
      learned_at: new Date().toISOString()
    });
    learnings.updated_at = new Date().toISOString();
    this.writeJson('learnings.json', learnings);
  }

  addMistake(mistake: string, lesson: string): void {
    const learnings = this.getLearnings();
    learnings.mistakes.push({
      mistake,
      lesson,
      date: new Date().toISOString()
    });
    learnings.updated_at = new Date().toISOString();
    this.writeJson('learnings.json', learnings);
  }

  addSuccess(success: string, whatWorked: string): void {
    const learnings = this.getLearnings();
    learnings.successes.push({
      success,
      what_worked: whatWorked,
      date: new Date().toISOString()
    });
    learnings.updated_at = new Date().toISOString();
    this.writeJson('learnings.json', learnings);
  }

  updateWorkingMemory(updates: Partial<WorkingMemory>): void {
    const current = this.getWorkingMemory();
    const updated = { ...current, ...updates, updated_at: new Date().toISOString() };
    this.writeJson('working_memory.json', updated);
  }

  setFocus(focus: string, context: WorkingMemory['active_context']): void {
    this.updateWorkingMemory({
      current_focus: focus,
      active_context: context
    });
  }

  saveConversationSummary(summary: Omit<ConversationSummary, 'id' | 'date'>): void {
    const id = Date.now().toString();
    const fullSummary: ConversationSummary = {
      id,
      date: new Date().toISOString(),
      ...summary
    };

    const filePath = path.join(
      this.memoryPath,
      'conversation_summaries',
      `${id}.json`
    );
    fs.writeFileSync(filePath, JSON.stringify(fullSummary, null, 2));
  }

  // ===== CONTEXTE INTELLIGENT =====

  /**
   * Construit un contexte optimisé pour le Brain
   * Au lieu de charger tout l'historique, on construit un contexte intelligent
   */
  buildContext(): string {
    const core = this.getCore();
    const projects = this.getProjects();
    const working = this.getWorkingMemory();
    const recentSummaries = this.getConversationSummaries(3);
    const learnings = this.getLearnings();

    let context = '## Mémoire Active\n\n';

    // Informations sur l'utilisateur
    if (core.user.name) {
      context += `### Utilisateur\n`;
      context += `- Nom: ${core.user.name}\n`;
      if (core.user.role) context += `- Rôle: ${core.user.role}\n`;
      context += '\n';
    }

    // Faits critiques et importants
    const importantFacts = core.facts.filter(f => 
      f.importance === 'critical' || f.importance === 'high'
    );
    if (importantFacts.length > 0) {
      context += `### Faits importants\n`;
      for (const fact of importantFacts) {
        context += `- [${fact.importance.toUpperCase()}] ${fact.fact}\n`;
      }
      context += '\n';
    }

    // Focus actuel
    if (working.current_focus) {
      context += `### Focus actuel\n`;
      context += `**${working.current_focus}**\n`;
      if (working.active_context.what_we_are_doing) {
        context += `- Ce qu'on fait: ${working.active_context.what_we_are_doing}\n`;
        context += `- Pourquoi: ${working.active_context.why}\n`;
        context += `- Étape actuelle: ${working.active_context.current_step}\n`;
      }
      context += '\n';
    }

    // Projets actifs
    const activeProjects = projects.active.filter(p => p.status === 'active' || p.status === 'paused');
    if (activeProjects.length > 0) {
      context += `### Projets en cours\n`;
      for (const project of activeProjects.slice(0, 3)) {
        const pendingTasks = project.tasks.filter(t => t.status !== 'done').length;
        context += `- **${project.name}** (${pendingTasks} tâches restantes)\n`;
      }
      context += '\n';
    }

    // Résumés des conversations récentes
    if (recentSummaries.length > 0) {
      context += `### Conversations récentes\n`;
      for (const summary of recentSummaries) {
        context += `- ${summary.date.split('T')[0]}: ${summary.summary}\n`;
      }
      context += '\n';
    }

    // Derniers apprentissages
    const recentInsights = learnings.insights.slice(-3);
    if (recentInsights.length > 0) {
      context += `### Apprentissages récents\n`;
      for (const insight of recentInsights) {
        context += `- ${insight.insight}\n`;
      }
      context += '\n';
    }

    return context;
  }

  /**
   * Analyse une conversation pour en extraire des informations
   * À appeler avec le Brain pour faire une vraie analyse sémantique
   */
  async analyzeConversation(
    messages: Anthropic.MessageParam[],
    brain: { think: (msg: string, ctx?: string) => Promise<{ text: string }> }
  ): Promise<{
    summary: string;
    facts: string[];
    decisions: string[];
  }> {
    // Construire un résumé des messages pour l'analyse
    const conversationText = messages
      .slice(-20) // Derniers 20 messages max
      .map(m => {
        const content = typeof m.content === 'string' 
          ? m.content 
          : JSON.stringify(m.content);
        return `${m.role}: ${content.slice(0, 500)}`;
      })
      .join('\n');

    const prompt = `Analyse cette conversation et extrais:
1. Un résumé en 1-2 phrases
2. Les faits importants appris (liste)
3. Les décisions prises (liste)

Conversation:
${conversationText}

Réponds en JSON strict:
{"summary": "...", "facts": ["...", "..."], "decisions": ["...", "..."]}`;

    try {
      const response = await brain.think(prompt);
      const parsed = JSON.parse(response.text);
      return {
        summary: parsed.summary || '',
        facts: parsed.facts || [],
        decisions: parsed.decisions || []
      };
    } catch {
      return { summary: '', facts: [], decisions: [] };
    }
  }

  // ===== UTILITAIRES =====

  private readJson<T>(filename: string): T {
    const filePath = path.join(this.memoryPath, filename);
    if (fs.existsSync(filePath)) {
      return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    }
    throw new Error(`Memory file not found: ${filename}`);
  }

  private writeJson(filename: string, data: unknown): void {
    const filePath = path.join(this.memoryPath, filename);
    fs.writeFileSync(filePath, JSON.stringify(data, null, 2));
  }

  /**
   * Export complet de la mémoire (pour debug/backup)
   */
  exportAll(): Record<string, unknown> {
    return {
      core: this.getCore(),
      projects: this.getProjects(),
      learnings: this.getLearnings(),
      working: this.getWorkingMemory(),
      summaries: this.getConversationSummaries(10)
    };
  }
}
